const ALIAS_TO_CANONICAL_SLUG: Record<string, string> = {};
for (const entry of Object.values(QUESTION_REVISION_REGISTRY)) {
  ALIAS_TO_CANONICAL_SLUG[entry.quizSlug] = entry.quizSlug;
  ALIAS_TO_CANONICAL_SLUG[entry.lessonId] = entry.quizSlug;
  ALIAS_TO_CANONICAL_SLUG[entry.quizId] = entry.quizSlug;
}

export function resolveCanonicalQuizSlug(slugOrId: string): string {
  return ALIAS_TO_CANONICAL_SLUG[slugOrId] || slugOrId;
}

export function getQuestionRevisionEntry(
  slugOrId: string,
  questionId: string
): QuestionRevisionEntry | undefined {
  const canonical = resolveCanonicalQuizSlug(slugOrId);
  return QUESTION_REVISION_REGISTRY[`${canonical}::${questionId}`];
}

export function getV1CorrectIndex(slugOrId: string, questionId: string): number | undefined {
  return getQuestionRevisionEntry(slugOrId, questionId)?.v1CorrectIndex;
}

export function getV2CorrectIndex(slugOrId: string, questionId: string): number | undefined {
  return getQuestionRevisionEntry(slugOrId, questionId)?.v2CorrectIndex;
}

/**
 * Translates a user's Revision 2 displayed choice indices back to Revision 1 canonical indices.
 * Used when submitting against a Revision 1 database prior to Migration 0011 cutover.
 */
export function translateV2AnswersToV1(
  slugOrId: string,
  answersV2: Record<string, number>
): Record<string, number> {
  const out: Record<string, number> = {};
  for (const [qId, v2Idx] of Object.entries(answersV2)) {
    const entry = getQuestionRevisionEntry(slugOrId, qId);
    if (entry && typeof v2Idx === "number" && v2Idx >= 0 && v2Idx < entry.v2ToV1Map.length) {
      out[qId] = entry.v2ToV1Map[v2Idx];
    } else {
      out[qId] = v2Idx;
    }
  }
  return out;
}
